 static JdbcTemplate role(DriverManagerDataSource base,String role){return new JdbcTemplate(new DelegatingDataSource(base){@Override public Connection getConnection()throws SQLException{var c=super.getConnection();try(var s=c.createStatement()){s.execute("SET ROLE "+role);s.execute("SET lock_timeout='2s'");s.execute("SET statement_timeout='10s'");}return c;}});}
 @BeforeEach void services(){review=new JdbcPrivateCaseReview(http,clock,ids);@SuppressWarnings("unchecked") ObjectProvider<ResourceRevisions> revisions=mock(ObjectProvider.class);when(revisions.getObject()).thenReturn(REVISIONS);service=new JdbcScopedRedactions(http,review,revisions,clock,ids);}
 record Fixture(UUID source,UUID organization,String country,UUID subject,UUID owner,PrivateCaseReview.Actor actor){}
 Fixture fixture(String country,String type,String role){UUID source=ids.next(),org=ids.next(),subject=ids.next(),ownerId=role.equals("OWNER")?subject:ids.next(),operator=ids.next(),session=ids.next();ownerTx.executeWithoutResult(s->{for(UUID id:new LinkedHashSet<>(List.of(subject,ownerId,operator)))owner.update("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state,created_at,updated_at) VALUES(?,?,?,true,'PRIVATE-DISPLAY-ČAJ','ACTIVE',?,?)",id,id.equals(operator)?"PLATFORM_ADMIN":"BUSINESS",id+"@example.com",at(),at());owner.update("INSERT INTO platform_account(id) VALUES(?)",operator);owner.update("INSERT INTO organization(id,type,country,currency,display_name,legal_name,registration_identifier,address_line1,address_city,address_postal_code,address_country,default_language,state,owner_account_id) VALUES(?,?,?,?,'Synthetic','Synthetic',?,'Synthetic','Synthetic','11000',?,'en','ACTIVE',?)",org,type,country,country.equals("RS")?"RSD":"BAM",org.toString(),country,ownerId);owner.update("INSERT INTO business_account(id,organization_id,role) VALUES(?,?,'OWNER')",ownerId,org);if(!subject.equals(ownerId))owner.update("INSERT INTO business_account(id,organization_id,role) VALUES(?,?,?)",subject,org,role);owner.execute("SET LOCAL narudzbine.operator_change_reference='SYN-SCOPED'");owner.update("INSERT INTO privacy_operator(account_id,created_at) VALUES(?,?)",operator,at());owner.update("INSERT INTO application_session(id,account_id,transport,token_hash,device_label,created_at,last_qualified_activity_at,absolute_expires_at,auth_at,auth_method_type,credential_generation,security_epoch) VALUES(?,?,'NATIVE',sha256(convert_to(?,'UTF8')),'Synthetic',?,?,?,?,'PASSWORD',0,0)",session,operator,session.toString(),at(),at(),Timestamp.from(NOW.plusSeconds(43200)),at());owner.update("INSERT INTO privacy_case(id,requester_id,organization_id,country,kind,private_reason,created_at) VALUES(?,?,?,?,'REDACTION','PRIVATE-CASE-REASON',?)",source,subject,org,country,at());if(!role.equals("OWNER"))owner.update("UPDATE account_identity SET state='DEACTIVATED',revision=revision+1,updated_at=? WHERE id=?",at(),subject);});return new Fixture(source,org,country,subject,ownerId,new PrivateCaseReview.Actor(operator,session,"NATIVE"));}
 Timestamp at(){return Timestamp.from(clock.instant());}
 void guards(Fixture f){http.queryForList("SELECT id FROM organization WHERE id=? FOR UPDATE",f.organization());http.queryForList("SELECT id FROM account_identity WHERE id=? FOR UPDATE",f.actor().account());http.queryForList("SELECT id FROM application_session WHERE id=? FOR UPDATE",f.actor().session());}
 PrivateCaseReview.Access authorize(Fixture f){return httpTx.execute(s->{guards(f);return review.authorize(f.source(),new PrivateCaseReview.Target(f.organization(),f.country()),f.actor(),new PrivateCaseReview.Context("Synthetic scope approval","SYN-SCOPE"));});}
 ScopedRedactions.Command command(Fixture f,UUID id){long revision=owner.queryForObject("SELECT coalesce((SELECT revision FROM privacy_redaction_progress WHERE case_id=?),1)",Long.class,f.source());return new ScopedRedactions.Command(id,REVISIONS.encode("privacy/v1",f.source(),revision),"ACCOUNT_DISPLAY_NAME_V1",new ScopedRedactions.References("SYN-REQUESTER","SYN-LEGAL","SYN-CONTAINED","SYN-RETAINED"),new PrivateCaseReview.Context("Synthetic scope approval","SYN-SCOPE"));}
 ScopedRedactions.View approve(Fixture f,ScopedRedactions.Command c){var a=authorize(f);return httpTx.execute(s->{guards(f);return service.approve(a,c);});}
 ScopedRedactions.View status(Fixture f,UUID id){return httpTx.execute(s->{guards(f);return service.read(f.actor(),f.source(),id);});}
 static class Store implements IndependentObjects {
  final ConcurrentHashMap<Key,byte[]> values=new ConcurrentHashMap<>();boolean failIntent,failCompletion,loseWrite;Runnable afterIntent;
  public boolean create(Key k,byte[] b){IndependentEvidence.outside();if(failIntent&&k.family()==Family.DELETION_INTENT||failCompletion&&k.family()==Family.DELETION_COMPLETION)throw new EvidenceFailure("EVIDENCE_UNAVAILABLE");boolean result=values.putIfAbsent(k,b.clone())==null;if(k.family()==Family.DELETION_INTENT&&afterIntent!=null){var callback=afterIntent;afterIntent=null;callback.run();}if(loseWrite){loseWrite=false;throw new EvidenceFailure("EVIDENCE_UNAVAILABLE");}return result;}
  public Optional<byte[]> read(Key k){IndependentEvidence.outside();return Optional.ofNullable(values.get(k)).map(byte[]::clone);}public Page list(Family f,int n,Key a){throw new UnsupportedOperationException();}
 }
 IndependentEvidence evidence(Store s){return new IndependentEvidence(s,Map.of("v1",new byte[32]),"v1",List.of());}
 ScopedRedactionWorker worker(IndependentEvidence e){return new ScopedRedactionWorker(executor,new DataSourceTransactionManager(executor.getDataSource()),e,clock,ids,"SYNTHETIC","SYN-SCOPED");}
 String name(Fixture f){return owner.queryForObject("SELECT display_name FROM account_identity WHERE id=?",String.class,f.subject());}
 @Test void actualCommittedScopedMutationAndCompletionInBothCountriesAndTypes(){for(String country:List.of("RS","BA"))for(String type:List.of("BUYER","VENDOR")){var f=fixture(country,type,"ADMIN");UUID id=ids.next();var c=command(f,id);var original=approve(f,c);assertThat(original.state()).isEqualTo("APPROVED");var before=owner.queryForMap("SELECT to_jsonb(a)-ARRAY['display_name','revision','updated_at'] AS snapshot FROM account_identity a WHERE id=?",f.subject());var store=new Store();var evidence=evidence(store);assertThat(worker(evidence).run(id,false).outcome()).isEqualTo("APPLIED");assertThat(name(f)).isEqualTo("[redacted]");assertThat(owner.queryForMap("SELECT to_jsonb(a)-ARRAY['display_name','revision','updated_at'] AS snapshot FROM account_identity a WHERE id=?",f.subject())).isEqualTo(before);assertThat(status(f,id).state()).isEqualTo("COMPLETED");assertThat(status(f,id).wholeCaseFulfillment()).isFalse();assertThat(owner.queryForObject("SELECT state FROM privacy_redaction_fulfillment_metadata WHERE case_id=?",String.class,f.source())).isEqualTo("REVIEWING");assertThat(approve(f,c)).isEqualTo(original);for(var family:List.of(IndependentObjects.Family.DELETION_INTENT,IndependentObjects.Family.DELETION_COMPLETION)){String plain=new String(evidence.read(new IndependentObjects.Key(family,f.source(),1)).orElseThrow().bytes(),java.nio.charset.StandardCharsets.UTF_8);assertThat(plain).doesNotContain("PRIVATE-DISPLAY-ČAJ","PRIVATE-CASE-REASON","@example.com","sessionTokenHash");}long revision=owner.queryForObject("SELECT revision FROM account_identity WHERE id=?",Long.class,f.subject());assertThat(worker(evidence).run(id,true).state()).isEqualTo("COMPLETED");assertThat(owner.queryForObject("SELECT revision FROM account_identity WHERE id=?",Long.class,f.subject())).isEqualTo(revision);}}
 @Test void failedIndependentIntentCannotChangeProfile(){var f=fixture("RS","BUYER","ADMIN");UUID id=ids.next();approve(f,command(f,id));var store=new Store();store.failIntent=true;assertThatThrownBy(()->worker(evidence(store)).run(id,false)).isInstanceOf(EvidenceFailure.class);assertThat(name(f)).isEqualTo("PRIVATE-DISPLAY-ČAJ");assertThat(status(f,id).state()).isEqualTo("APPROVED");}
 @Test void actualApplyCommitFailureRollsBackNameAndKeepsVerifiedIntent(){var f=fixture("BA","VENDOR","ADMIN");UUID id=ids.next();approve(f,command(f,id));var store=new Store();var evidence=evidence(store);owner.execute("CREATE FUNCTION synthetic_scoped_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='PRIVACY_REDACTION_APPLIED' THEN RAISE EXCEPTION 'Synthetic scoped commit failure';END IF;RETURN NULL;END $$");owner.execute("CREATE CONSTRAINT TRIGGER tr_synthetic_scoped_failure AFTER INSERT ON audit_event DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION synthetic_scoped_failure()");try{assertThatThrownBy(()->worker(evidence).run(id,false)).isInstanceOf(org.springframework.transaction.TransactionSystemException.class);}finally{owner.execute("DROP TRIGGER tr_synthetic_scoped_failure ON audit_event");owner.execute("DROP FUNCTION synthetic_scoped_failure()");}assertThat(name(f)).isEqualTo("PRIVATE-DISPLAY-ČAJ");assertThat(status(f,id).state()).isEqualTo("INTENT_VERIFIED");assertThat(worker(evidence).run(id,false).state()).isEqualTo("COMPLETED");}
 @Test void completionFailureRetainsAppliedSourceAndResumesAfterApprovalExpiry(){var f=fixture("RS","VENDOR","ADMIN");UUID id=ids.next();approve(f,command(f,id));var store=new Store();store.loseWrite=true;store.failCompletion=true;var e=evidence(store);assertThatThrownBy(()->worker(e).run(id,false)).isInstanceOf(EvidenceFailure.class);assertThat(name(f)).isEqualTo("[redacted]");long version=owner.queryForObject("SELECT revision FROM account_identity WHERE id=?",Long.class,f.subject());clock.at=NOW.plusSeconds(600);store.failCompletion=false;assertThat(worker(e).run(id,true).state()).isEqualTo("COMPLETED");assertThat(owner.queryForObject("SELECT revision FROM account_identity WHERE id=?",Long.class,f.subject())).isEqualTo(version);}
 @Test void staleProfileAndExpiredAuthorityCannotBeSilentlyApplied(){for(String changed:List.of("profile","expiry","qualification")){var f=fixture("BA","BUYER","ADMIN");UUID id=ids.next();approve(f,command(f,id));var store=new Store();store.afterIntent=()->{if(changed.equals("profile"))owner.update("UPDATE account_identity SET display_name='NEW-PRIVATE-NAME',revision=revision+1 WHERE id=?",f.subject());if(changed.equals("expiry"))clock.at=NOW.plusSeconds(60);if(changed.equals("qualification"))ownerTx.executeWithoutResult(s->{owner.execute("SET LOCAL narudzbine.operator_change_reference='SYN-REVOKE'");owner.update("UPDATE privacy_operator SET enabled=false,revision=revision+1 WHERE account_id=?",f.actor().account());});};assertThatThrownBy(()->worker(evidence(store)).run(id,false)).isInstanceOf(EvidenceFailure.class);assertThat(name(f)).isNotEqualTo("[redacted]");clock.at=NOW;}}
 @Test void cancellationProducesVerifiedCancelledCompletionWithoutProfileMutation(){var f=fixture("RS","BUYER","ADMIN");UUID id=ids.next();var original=approve(f,command(f,id));var a=authorize(f);var context=new PrivateCaseReview.Context("Synthetic cancel","SYN-CANCEL");var cancelled=httpTx.execute(s->{guards(f);return service.cancel(a,id,original.revision(),context);});assertThat(cancelled.state()).isEqualTo("CANCELLED");var store=new Store();assertThat(worker(evidence(store)).run(id,true).outcome()).isEqualTo("CANCELLED");assertThat(name(f)).isEqualTo("PRIVATE-DISPLAY-ČAJ");var next=authorize(f);ScopedRedactions.View replay=httpTx.execute(s->{guards(f);return service.cancel(next,id,original.revision(),context);});assertThat(replay).isEqualTo(cancelled);}
 @Test void workerAuthorityIsNarrowAndMissingKnownEvidenceIsNeverRecreated(){ScopedRedactionAuthority.verify(executor);assertThatThrownBy(()->ScopedRedactionAuthority.verify(owner)).isInstanceOf(IllegalStateException.class);var f=fixture("BA","BUYER","ADMIN");UUID id=ids.next();approve(f,command(f,id));var store=new Store();var e=evidence(store);assertThat(worker(e).run(id,false).state()).isEqualTo("COMPLETED");var key=new IndependentObjects.Key(IndependentObjects.Family.DELETION_COMPLETION,f.source(),1);store.values.remove(key);assertThatThrownBy(()->worker(e).run(id,true)).isInstanceOf(EvidenceFailure.class);assertThat(store.values).doesNotContainKey(key);assertThat(name(f)).isEqualTo("[redacted]");}
