 @Test void twoIndependentWorkersConvergeOnOneMutationAndOneCompletion()throws Exception{var f=fixture("BA","BUYER","ADMIN");UUID id=ids.next();approve(f,command(f,id));var store=new Store();var e=evidence(store);var start=new CountDownLatch(1);try(var threads=Executors.newFixedThreadPool(2)){var first=threads.submit(()->{start.await();return worker(e).run(id,false);});var second=threads.submit(()->{start.await();return worker(e).run(id,false);});start.countDown();assertThat(first.get(15,TimeUnit.SECONDS).state()).isEqualTo("COMPLETED");assertThat(second.get(15,TimeUnit.SECONDS).state()).isEqualTo("COMPLETED");}assertThat(owner.queryForObject("SELECT count(*) FROM audit_event WHERE resource_id=? AND action='PRIVACY_REDACTION_APPLIED'",Integer.class,id)).isEqualTo(1);assertThat(owner.queryForObject("SELECT revision FROM account_identity WHERE id=?",Long.class,f.subject())).isEqualTo(3);assertThat(store.values).hasSize(2);}
 @Test void alreadyRedactedProfileRecordsNoChange(){var f=fixture("RS","BUYER","ADMIN");owner.update("UPDATE account_identity SET display_name='[redacted]',revision=revision+1 WHERE id=?",f.subject());UUID id=ids.next();approve(f,command(f,id));assertThat(worker(evidence(new Store())).run(id,false).state()).isEqualTo("COMPLETED");assertThat(status(f,id).fieldChanged()).isFalse();assertThat(owner.queryForObject("SELECT revision FROM account_identity WHERE id=?",Long.class,f.subject())).isEqualTo(3);}
 @Test void holdActivatedAfterIntentPreventsApplication(){var f=fixture("BA","VENDOR","ADMIN");UUID id=ids.next();approve(f,command(f,id));@SuppressWarnings("unchecked") ObjectProvider<ResourceRevisions> r=mock(ObjectProvider.class);when(r.getObject()).thenReturn(REVISIONS);var holds=new JdbcRetentionHolds(owner,new JdbcPrivateCaseReview(owner,clock,ids),clock,ids,r);UUID hold=ids.next();RetentionHolds.View[] current=new RetentionHolds.View[1];var store=new Store();store.afterIntent=()->current[0]=ownerTx.execute(t->holds.activate(f.actor(),f.source(),new PrivateCaseReview.Target(f.organization(),f.country()),hold,new RetentionHolds.Context("Synthetic late hold","SYN-HOLD")));try{assertThatThrownBy(()->worker(evidence(store)).run(id,false)).isInstanceOf(EvidenceFailure.class).extracting(e->((EvidenceFailure)e).code()).isEqualTo("HOLD_ACTIVE");assertThat(name(f)).isEqualTo("PRIVATE-DISPLAY-ČAJ");}finally{if(current[0]!=null)ownerTx.executeWithoutResult(t->holds.release(f.actor(),f.source(),hold,current[0].revision(),new RetentionHolds.Context("Synthetic release","SYN-RELEASE")));}}
 @Test void explicitCommandReadsCommittedCompletionUsingIsolatedLoginAndLocalStore(@org.junit.jupiter.api.io.TempDir java.nio.file.Path root){var f=fixture("RS","VENDOR","ADMIN");UUID id=ids.next();approve(f,command(f,id));var objects=new FileIndependentObjectStore(root);var e=new IndependentEvidence(objects,Map.of("v1",new byte[32]),"v1",List.of());assertThat(worker(e).run(id,false).state()).isEqualTo("COMPLETED");owner.execute("ALTER ROLE scoped_executor LOGIN PASSWORD 'synthetic-command-only'");try{var env=new HashMap<String,String>();env.put("REDACTION_WORKER_MODE","LOCAL_SYNTHETIC");env.put("REDACTION_WORKER_ENVIRONMENT","SYNTHETIC");env.put("REDACTION_WORKER_CONFIGURATION_REFERENCE","SYN-SCOPED");env.put("REDACTION_WORKER_JDBC_URL",DB.getJdbcUrl());env.put("REDACTION_WORKER_USERNAME","scoped_executor");env.put("REDACTION_WORKER_PASSWORD","synthetic-command-only");env.put("REDACTION_WORKER_LOCAL_ROOT",root.toString());env.put("REDACTION_WORKER_LOCAL_SYNTHETIC_ACKNOWLEDGED","true");env.put("REDACTION_WORKER_ACTIVE_KEY_VERSION","v1");env.put("REDACTION_WORKER_KEY_RING","{\"v1\":\""+Base64.getEncoder().encodeToString(new byte[32])+"\"}");ScopedRedactionWorkerCommand.run(new String[]{"--redaction-worker",id.toString(),"--completion-only"},env);}finally{owner.execute("ALTER ROLE scoped_executor NOLOGIN PASSWORD NULL");}assertThat(name(f)).isEqualTo("[redacted]");}
