 static final UUID IDENTITY_TENANT=UUID.fromString("019a0b00-0000-7000-8000-000000000100");
 static final String IDENTITY_ENDPOINT="https://synthetic.example/api/login";
 void emailSource(Fixture f){
  owner.update("UPDATE privacy_redaction_executor SET revision=revision+1,identity_endpoint=?,identity_tenant_id=?,identity_conformance_reference='SYN-IDENTITY',updated_at=greatest(updated_at,?) WHERE identity_endpoint IS DISTINCT FROM ? OR identity_tenant_id IS DISTINCT FROM ?",IDENTITY_ENDPOINT,IDENTITY_TENANT,at(),IDENTITY_ENDPOINT,IDENTITY_TENANT);
  owner.update("INSERT INTO managed_password_identity(account_id,tenant_id,provider_user_id) VALUES(?,?,?)",f.subject(),IDENTITY_TENANT,f.subject());
 }
 ScopedRedactions.Command emailCommand(Fixture f,UUID id){var c=command(f,id);return new ScopedRedactions.Command(c.id(),c.expectedCaseRevision(),"ACCOUNT_EMAIL_V1",c.references(),c.context());}
 ScopedRedactionWorker emailWorker(IndependentEvidence e,ManagedIdentityContainment identity){return new ScopedRedactionWorker(executor,new DataSourceTransactionManager(executor.getDataSource()),e,clock,ids,"SYNTHETIC","SYN-SCOPED",identity);}
 ManagedIdentityContainment inactive(){return subject->{IndependentEvidence.outside();return Optional.of(new ManagedIdentityContainment.Observation(subject,ManagedIdentityContainment.State.INACTIVE,clock.instant()));};}
 @Test void emailRetirementAtomicallyChangesOnlyAuthorizedFieldsAndClaimsAcrossCountries(){
  for(String country:List.of("RS","BA"))for(String type:List.of("BUYER","VENDOR")){
   var f=fixture(country,type,"ADMIN");emailSource(f);UUID id=ids.next();var c=emailCommand(f,id);var approved=approve(f,c);
   var before=owner.queryForMap("SELECT to_jsonb(a)-ARRAY['email','email_verified','privacy_retired_at','security_epoch','credential_generation','revision','updated_at'] AS snapshot FROM account_identity a WHERE id=?",f.subject());
   var store=new Store();var e=evidence(store);var result=emailWorker(e,inactive()).run(id,false);assertThat(result.state()).isEqualTo("COMPLETED");assertThat(result.affectedCounts()).containsEntry("account_identity",1L).hasSize(7);
   assertThat(owner.queryForMap("SELECT to_jsonb(a)-ARRAY['email','email_verified','privacy_retired_at','security_epoch','credential_generation','revision','updated_at'] AS snapshot FROM account_identity a WHERE id=?",f.subject())).isEqualTo(before);
   var row=owner.queryForMap("SELECT email,email_verified,state,privacy_retired_at,security_epoch,credential_generation,revision FROM account_identity WHERE id=?",f.subject());assertThat(row).containsEntry("email","retired+"+f.subject()+"@accounts.invalid").containsEntry("email_verified",false).containsEntry("state","DEACTIVATED").containsEntry("security_epoch",1L).containsEntry("credential_generation",1L).containsEntry("revision",3L);assertThat(row.get("privacy_retired_at")).isNotNull();
   assertThat(owner.queryForObject("SELECT count(*) FROM login_email_claim WHERE account_id=? AND kind='CURRENT' AND email=?",Integer.class,f.subject(),row.get("email"))).isEqualTo(1);
   assertThat(owner.queryForObject("SELECT count(*) FROM login_email_claim WHERE email=?",Integer.class,f.subject()+"@example.com")).isZero();
   assertThat(owner.queryForObject("SELECT count(*) FROM credential_operation WHERE account_id=?",Integer.class,f.subject())).isZero();
   assertThat(approve(f,c)).isEqualTo(approved);assertThat(worker(e).run(id,true).state()).isEqualTo("COMPLETED");
   for(var family:List.of(IndependentObjects.Family.DELETION_INTENT,IndependentObjects.Family.DELETION_COMPLETION)){String plain=new String(e.read(new IndependentObjects.Key(family,f.source(),1)).orElseThrow().bytes(),java.nio.charset.StandardCharsets.UTF_8);assertThat(plain).doesNotContain(f.subject()+"@example.com","PRIVATE-DISPLAY","PRIVATE-CASE-REASON");}
   assertThatThrownBy(()->owner.update("UPDATE account_identity SET state='ACTIVE',revision=revision+1 WHERE id=?",f.subject())).isInstanceOf(org.springframework.dao.DataAccessException.class);
   assertThatThrownBy(()->owner.update("UPDATE account_identity SET email_verified=true,revision=revision+1 WHERE id=?",f.subject())).isInstanceOf(org.springframework.dao.DataAccessException.class);
   assertThatThrownBy(()->owner.update("UPDATE account_identity SET privacy_retired_at=NULL WHERE id=?",f.subject())).isInstanceOf(org.springframework.dao.DataAccessException.class);
  }
 }
 @Test void emailWithoutVerifierUnknownWrongSourceAndExpiredObservationCannotMutate(){
  for(String failure:List.of("missing","unknown","wrong-source","expired","future")){
   var f=fixture("RS","BUYER","ADMIN");emailSource(f);UUID id=ids.next();approve(f,emailCommand(f,id));var e=evidence(new Store());
   ManagedIdentityContainment verifier=subject->{if(failure.equals("unknown"))return Optional.empty();var expected=failure.equals("wrong-source")?new ManagedIdentityContainment.Subject(subject.tenantId(),ids.next(),subject.endpoint(),subject.conformanceReference(),subject.allowAbsence()):subject;return Optional.of(new ManagedIdentityContainment.Observation(expected,ManagedIdentityContainment.State.INACTIVE,clock.instant().plusSeconds(failure.equals("expired")?-15:failure.equals("future")?1:0)));};
   assertThatThrownBy(()->emailWorker(e,failure.equals("missing")?null:verifier).run(id,false)).isInstanceOf(EvidenceFailure.class);
   assertThat(owner.queryForObject("SELECT email FROM account_identity WHERE id=?",String.class,f.subject())).isEqualTo(f.subject()+"@example.com");assertThat(owner.queryForObject("SELECT privacy_retired_at IS NULL FROM account_identity WHERE id=?",Boolean.class,f.subject())).isTrue();
  }
 }
 @Test void emailCompletionLossResumesWithoutProviderAndDoesNotRepeatSourceMutation(){
  var f=fixture("BA","VENDOR","ADMIN");emailSource(f);UUID id=ids.next();approve(f,emailCommand(f,id));var store=new Store();store.failCompletion=true;var e=evidence(store);
  assertThatThrownBy(()->emailWorker(e,inactive()).run(id,false)).isInstanceOf(EvidenceFailure.class);assertThat(status(f,id).state()).isEqualTo("APPLIED");long revision=owner.queryForObject("SELECT revision FROM account_identity WHERE id=?",Long.class,f.subject());clock.at=NOW.plusSeconds(600);try{store.failCompletion=false;assertThat(worker(e).run(id,true).state()).isEqualTo("COMPLETED");assertThat(owner.queryForObject("SELECT revision FROM account_identity WHERE id=?",Long.class,f.subject())).isEqualTo(revision);}finally{clock.at=NOW;}
 }
 @Test void emailLateSourceOrAuthorityChangeRejectsObservedContainment(){
  for(String change:List.of("profile","expiry","qualification")){
   var f=fixture("BA","BUYER","ADMIN");emailSource(f);UUID id=ids.next();approve(f,emailCommand(f,id));var e=evidence(new Store());
   ManagedIdentityContainment verifier=subject->{IndependentEvidence.outside();if(change.equals("profile"))owner.update("UPDATE account_identity SET display_name='Changed',revision=revision+1 WHERE id=?",f.subject());if(change.equals("expiry"))clock.at=NOW.plusSeconds(60);if(change.equals("qualification"))ownerTx.executeWithoutResult(t->{owner.execute("SET LOCAL narudzbine.operator_change_reference='SYN-REVOKE'");owner.update("UPDATE privacy_operator SET enabled=false,revision=revision+1 WHERE account_id=?",f.actor().account());});return Optional.of(new ManagedIdentityContainment.Observation(subject,ManagedIdentityContainment.State.INACTIVE,clock.instant()));};
   try{assertThatThrownBy(()->emailWorker(e,verifier).run(id,false)).isInstanceOf(EvidenceFailure.class);assertThat(owner.queryForObject("SELECT email FROM account_identity WHERE id=?",String.class,f.subject())).endsWith("@example.com");}finally{clock.at=NOW;}
  }
 }

 @Test void emailConcurrentWorkersConvergeAndAlreadyRetiredSourceIsAnExplicitNoOp()throws Exception{
  var f=fixture("BA","BUYER","ADMIN");emailSource(f);UUID id=ids.next();approve(f,emailCommand(f,id));var store=new Store();var e=evidence(store);var start=new CountDownLatch(1);
  try(var threads=Executors.newFixedThreadPool(2)){var first=threads.submit(()->{start.await();return emailWorker(e,inactive()).run(id,false);});var second=threads.submit(()->{start.await();return emailWorker(e,inactive()).run(id,false);});start.countDown();assertThat(first.get(15,TimeUnit.SECONDS).state()).isEqualTo("COMPLETED");assertThat(second.get(15,TimeUnit.SECONDS).state()).isEqualTo("COMPLETED");}
  assertThat(owner.queryForObject("SELECT count(*) FROM audit_event WHERE resource_id=? AND action='PRIVACY_REDACTION_APPLIED'",Integer.class,id)).isEqualTo(1);assertThat(owner.queryForObject("SELECT revision FROM account_identity WHERE id=?",Long.class,f.subject())).isEqualTo(3);
  UUID next=ids.next();approve(f,emailCommand(f,next));var noop=emailWorker(e,inactive()).run(next,false);assertThat(noop.affectedCounts()).containsEntry("account_identity",0L);assertThat(status(f,next).fieldChanged()).isFalse();assertThat(owner.queryForObject("SELECT revision FROM account_identity WHERE id=?",Long.class,f.subject())).isEqualTo(3);
 }
 @Test void emailActualCommitFailureRollsBackEmailClaimsAndRetirementTogether(){
  var f=fixture("RS","BUYER","ADMIN");emailSource(f);UUID id=ids.next();approve(f,emailCommand(f,id));var e=evidence(new Store());
  owner.execute("CREATE FUNCTION synthetic_email_commit_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='PRIVACY_REDACTION_APPLIED' THEN RAISE EXCEPTION 'Synthetic email commit failure';END IF;RETURN NULL;END $$");owner.execute("CREATE CONSTRAINT TRIGGER tr_synthetic_email_commit_failure AFTER INSERT ON audit_event DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION synthetic_email_commit_failure()");
  try{assertThatThrownBy(()->emailWorker(e,inactive()).run(id,false)).isInstanceOf(org.springframework.transaction.TransactionSystemException.class);}finally{owner.execute("DROP TRIGGER tr_synthetic_email_commit_failure ON audit_event");owner.execute("DROP FUNCTION synthetic_email_commit_failure()");}
  assertThat(owner.queryForObject("SELECT email FROM account_identity WHERE id=?",String.class,f.subject())).isEqualTo(f.subject()+"@example.com");assertThat(owner.queryForObject("SELECT count(*) FROM login_email_claim WHERE email=? AND kind='CURRENT'",Integer.class,f.subject()+"@example.com")).isEqualTo(1);assertThat(owner.queryForObject("SELECT count(*) FROM login_email_claim WHERE email=?",Integer.class,"retired+"+f.subject()+"@accounts.invalid")).isZero();assertThat(owner.queryForObject("SELECT privacy_retired_at IS NULL FROM account_identity WHERE id=?",Boolean.class,f.subject())).isTrue();assertThat(status(f,id).state()).isEqualTo("INTENT_VERIFIED");assertThat(emailWorker(e,inactive()).run(id,false).state()).isEqualTo("COMPLETED");
 }
 @Test void cancelledEmailActionNeverCallsProviderOrChangesClaims(){var f=fixture("RS","VENDOR","ADMIN");emailSource(f);UUID id=ids.next();var original=approve(f,emailCommand(f,id));var access=authorize(f);httpTx.executeWithoutResult(t->{guards(f);service.cancel(access,id,original.revision(),new PrivateCaseReview.Context("Synthetic cancel","SYN-CANCEL"));});var result=emailWorker(evidence(new Store()),subject->{throw new AssertionError("Provider must not be called after cancellation");}).run(id,true);assertThat(result.outcome()).isEqualTo("CANCELLED");assertThat(owner.queryForObject("SELECT email FROM account_identity WHERE id=?",String.class,f.subject())).endsWith("@example.com");}

 @Test void emailReservedSurrogateAndLateHoldNeverReleaseOriginalClaim(){
  for(String blocker:List.of("claim","hold")){
   var f=fixture("BA","VENDOR","ADMIN");emailSource(f);UUID id=ids.next();approve(f,emailCommand(f,id));var e=evidence(new Store());UUID other=ids.next();RetentionHolds.View[] held=new RetentionHolds.View[1];
   @SuppressWarnings("unchecked") ObjectProvider<ResourceRevisions> r=mock(ObjectProvider.class);when(r.getObject()).thenReturn(REVISIONS);var holds=new JdbcRetentionHolds(owner,new JdbcPrivateCaseReview(owner,clock,ids),clock,ids,r);UUID hold=ids.next();
   ManagedIdentityContainment verifier=subject->{IndependentEvidence.outside();if(blocker.equals("claim"))ownerTx.executeWithoutResult(t->{owner.update("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state) VALUES(?,'PLATFORM_ADMIN',?,true,'Synthetic','ACTIVE')",other,"retired+"+f.subject()+"@accounts.invalid");owner.update("INSERT INTO platform_account(id) VALUES(?)",other);});else held[0]=ownerTx.execute(t->holds.activate(f.actor(),f.source(),new PrivateCaseReview.Target(f.organization(),f.country()),hold,new RetentionHolds.Context("Synthetic late hold","SYN-HOLD")));return Optional.of(new ManagedIdentityContainment.Observation(subject,ManagedIdentityContainment.State.INACTIVE,clock.instant()));};
   try{assertThatThrownBy(()->emailWorker(e,verifier).run(id,false)).isInstanceOf(EvidenceFailure.class).extracting(v->((EvidenceFailure)v).code()).isEqualTo(blocker.equals("claim")?"EMAIL_ALREADY_RESERVED":"HOLD_ACTIVE");assertThat(owner.queryForObject("SELECT email FROM account_identity WHERE id=?",String.class,f.subject())).isEqualTo(f.subject()+"@example.com");assertThat(owner.queryForObject("SELECT count(*) FROM login_email_claim WHERE email=? AND kind='CURRENT'",Integer.class,f.subject()+"@example.com")).isEqualTo(1);}finally{if(held[0]!=null)ownerTx.executeWithoutResult(t->holds.release(f.actor(),f.source(),hold,held[0].revision(),new RetentionHolds.Context("Synthetic release","SYN-RELEASE")));}
  }
  for(String sql:List.of("SELECT * FROM privacy_identity_observation","INSERT INTO privacy_identity_observation(id) VALUES(gen_random_uuid())","SELECT identity_observation_snapshot(gen_random_uuid())","UPDATE account_identity SET privacy_retired_at=now()"))assertThatThrownBy(()->executor.execute(sql)).isInstanceOf(org.springframework.dao.DataAccessException.class);
  assertThatThrownBy(()->http.execute("SELECT acknowledge_identity_containment(NULL,NULL,'INACTIVE',now(),now())")).isInstanceOf(org.springframework.dao.DataAccessException.class);
 }

